1	/**
2	 * A focused re-implementation of CPython 3.12's `argparse`, covering the surface the
3	 * ported script uses: long options with a `type` converter, `required`, and the
4	 * automatic `-h/--help`. It reproduces argparse's message wording, usage/help
5	 * layout, error precedence and exit codes.
6	 *
7	 * Deliberately unsupported: positional arguments, nargs other than 0 or 1,
8	 * subparsers, groups. The parser being ported declares none of them.
9	 */
10	
11	import { reprStr } from '../python/repr.mjs';
12	
13	/** Raised for an error attributable to one action; rendered as "argument --x: ...". */
14	export class ArgumentError extends Error {
15	  constructor(action, message) {
16	    super(`argument ${action.optionStrings[0]}: ${message}`);
17	  }
18	}
19	
20	/**
21	 * Thrown instead of calling `process.exit`, so buffered stdout/stderr writes are
22	 * flushed before the process ends (`process.exit` can truncate a piped stdout).
23	 */
24	export class ParserExit extends Error {
25	  constructor(status) {
26	    super(`parser exit ${status}`);
27	    this.status = status;
28	  }
29	}
30	
31	/** argparse's `_negative_number_matcher`; Python's `\d` is the Unicode Nd category. */
32	const NEGATIVE_NUMBER = /^-\p{Nd}+$|^-\p{Nd}*\.\p{Nd}+$/u;
33	
34	const INDENT = '  ';
35	const MAX_HELP_POSITION = 24;
36	
37	export class ArgumentParser {
38	  constructor({ prog }) {
39	    this.prog = prog;
40	    this._actions = [];
41	    this._optionStringActions = new Map();
42	    this.addArgument(['-h', '--help'], { action: 'help', help: 'show this help message and exit' });
43	  }
44	
45	  addArgument(optionStrings, { action = 'store', type = null, required = false, metavar = null, help = null } = {}) {
46	    const dest = optionStrings[optionStrings.length - 1].replace(/^-+/, '').replace(/-/g, '_');
47	    const entry = {
48	      optionStrings,
49	      dest,
50	      action,
51	      type,
52	      required,
53	      // argparse defaults an optional's metavar to the upper-cased dest.
54	      metavar: metavar ?? dest.toUpperCase(),
55	      help,
56	      nargs: action === 'help' ? 0 : 1,
57	    };
58	    this._actions.push(entry);
59	    for (const optionString of optionStrings) this._optionStringActions.set(optionString, entry);
60	    return entry;
61	  }
62	
63	  // ---------------------------------------------------------------- formatting
64	
65	  _invocation(action) {
66	    if (action.nargs === 0) return action.optionStrings.join(', ');
67	    return action.optionStrings.map((option) => `${option} ${action.metavar}`).join(', ');
68	  }
69	
70	  formatUsage() {
71	    const parts = this._actions.map((action) => {
72	      const invocation =
73	        action.nargs === 0 ? action.optionStrings[0] : `${action.optionStrings[0]} ${action.metavar}`;
74	      return action.required ? invocation : `[${invocation}]`;
75	    });
76	    return `usage: ${this.prog}${parts.length ? ' ' : ''}${parts.join(' ')}\n`;
77	  }
78	
79	  formatHelp() {
80	    const invocations = this._actions.map((action) => this._invocation(action));
81	    // argparse aligns help text at min(longest invocation + indent + 2, 24).
82	    const actionMaxLength = Math.max(...invocations.map((text) => text.length + INDENT.length));
83	    const helpPosition = Math.min(actionMaxLength + 2, MAX_HELP_POSITION);
84	
85	    const lines = [this.formatUsage(), '\n', 'options:\n'];
86	    this._actions.forEach((action, index) => {
87	      const header = `${INDENT}${invocations[index]}`;
88	      if (action.help === null) {
89	        lines.push(`${header}\n`);
90	      } else if (header.length + 2 <= helpPosition) {
91	        lines.push(`${header.padEnd(helpPosition)}${action.help}\n`);
92	      } else {
93	        lines.push(`${header}\n${' '.repeat(helpPosition)}${action.help}\n`);
94	      }
95	    });
96	    return `${lines.join('').replace(/^\n+|\n+$/g, '')}\n`;
97	  }
98	
99	  printHelp() {
100	    process.stdout.write(this.formatHelp());
101	  }
102	
103	  /** argparse's `error()`: usage plus one message on stderr, exit status 2. */
104	  error(message) {
105	    process.stderr.write(this.formatUsage());
106	    process.stderr.write(`${this.prog}: error: ${message}\n`);
107	    throw new ParserExit(2);
108	  }
109	
110	  // ------------------------------------------------------------------ parsing
111	
112	  /**
113	   * argparse's `_parse_optional`. Returns null when the token is a positional,
114	   * `[action, optionString, explicitArg]` for a recognised option, or
115	   * `[null, token, null]` for something option-shaped but unknown.
116	   */
117	  _parseOptional(argString) {
118	    if (argString === '') return null;
119	    if (argString[0] !== '-') return null;
120	
121	    const exact = this._optionStringActions.get(argString);
122	    if (exact !== undefined) return [exact, argString, null];
123	    if (argString.length === 1) return null;
124	
125	    const separator = argString.indexOf('=');
126	    if (separator !== -1) {
127	      const optionString = argString.slice(0, separator);
128	      const known = this._optionStringActions.get(optionString);
129	      if (known !== undefined) return [known, optionString, argString.slice(separator + 1)];
130	    }
131	
132	    const candidates = this._getOptionTuples(argString);
133	    if (candidates.length > 1) {
134	      const matches = candidates.map(([, optionString]) => optionString).join(', ');
135	      this.error(`ambiguous option: ${argString} could match ${matches}`);
136	    }
137	    if (candidates.length === 1) return candidates[0];
138	
139	    // Looks like a negative number, and no option string does: treat as a value.
140	    if (NEGATIVE_NUMBER.test(argString)) return null;
141	    if (argString.includes(' ')) return null;
142	    return [null, argString, null];
143	  }
144	
145	  /** argparse's `_get_option_tuples`: abbreviated long options and bundled short ones. */
146	  _getOptionTuples(argString) {
147	    const result = [];
148	    if (argString.startsWith('--')) {
149	      const separator = argString.indexOf('=');
150	      const prefix = separator === -1 ? argString : argString.slice(0, separator);
151	      const explicitArg = separator === -1 ? null : argString.slice(separator + 1);
152	      for (const [optionString, action] of this._optionStringActions) {
153	        if (optionString.startsWith(prefix)) result.push([action, optionString, explicitArg]);
154	      }
155	    } else {
156	      const shortPrefix = argString.slice(0, 2);
157	      const shortExplicitArg = argString.slice(2);
158	      for (const [optionString, action] of this._optionStringActions) {
159	        if (optionString === shortPrefix) result.push([action, optionString, shortExplicitArg]);
160	        else if (optionString.startsWith(argString)) result.push([action, optionString, null]);
161	      }
162	    }
163	    return result;
164	  }
165	
166	  parseKnownArgs(argStrings) {
167	    const namespace = Object.create(null);
168	    for (const action of this._actions) {
169	      if (action.action === 'store') namespace[action.dest] = undefined;
170	    }
171	
172	    // Classify every token up front, as argparse does: 'O' for option, 'A' for a
173	    // value/positional, '-' for the end-of-options separator.
174	    const pattern = [];
175	    const optionTuples = new Map();
176	    let afterSeparator = false;
177	    argStrings.forEach((argString, index) => {
178	      if (!afterSeparator && argString === '--') {
179	        afterSeparator = true;
180	        pattern.push('-');
181	        return;
182	      }
183	      if (afterSeparator) {
184	        pattern.push('A');
185	        return;
186	      }
187	      const tuple = this._parseOptional(argString);
188	      if (tuple === null) {
189	        pattern.push('A');
190	      } else {
191	        optionTuples.set(index, tuple);
192	        pattern.push('O');
193	      }
194	    });
195	
196	    const extras = [];
197	    const seen = new Set();
198	
199	    const takeAction = (action, argument) => {
200	      seen.add(action);
201	      if (action.action === 'help') {
202	        this.printHelp();
203	        throw new ParserExit(0);
204	      }
205	      namespace[action.dest] = this._getValue(action, argument);
206	    };
207	
208	    let index = 0;
209	    while (index < argStrings.length) {
210	      const tuple = optionTuples.get(index);
211	      if (tuple === undefined) {
212	        // No positionals are declared, so every non-option token is left over.
213	        extras.push(argStrings[index]);
214	        index += 1;
215	        continue;
216	      }
217	      const [action, , explicitArg] = tuple;
218	      if (action === null) {
219	        extras.push(argStrings[index]);
220	        index += 1;
221	        continue;
222	      }
223	      if (explicitArg !== null) {
224	        if (action.nargs === 0) {
225	          throw new ArgumentError(action, `ignored explicit argument ${reprStr(explicitArg)}`);
226	        }
227	        takeAction(action, explicitArg);
228	        index += 1;
229	        continue;
230	      }
231	      if (action.nargs === 0) {
232	        takeAction(action, null);
233	        index += 1;
234	        continue;
235	      }
236	      if (pattern[index + 1] !== 'A') {
237	        throw new ArgumentError(action, 'expected one argument');
238	      }
239	      takeAction(action, argStrings[index + 1]);
240	      index += 2;
241	    }
242	
243	    // Missing required options are reported before leftover tokens are.
244	    const missing = this._actions
245	      .filter((action) => action.required && !seen.has(action))
246	      .map((action) => action.optionStrings[0]);
247	    if (missing.length > 0) {
248	      this.error(`the following arguments are required: ${missing.join(', ')}`);
249	    }
250	
251	    return [namespace, extras];
252	  }
253	
254	  parseArgs(argStrings) {
255	    let namespace;
256	    let extras;
257	    try {
258	      [namespace, extras] = this.parseKnownArgs(argStrings);
259	    } catch (err) {
260	      if (err instanceof ArgumentError) this.error(err.message);
261	      throw err;
262	    }
263	    if (extras.length > 0) {
264	      this.error(`unrecognized arguments: ${extras.join(' ')}`);
265	    }
266	    return namespace;
267	  }
268	
269	  /** argparse's `_get_value`: run the converter, reporting failures per action. */
270	  _getValue(action, argString) {
271	    if (action.type === null) return argString;
272	    try {
273	      return action.type(argString);
274	    } catch {
275	      const typeName = action.type.pyName ?? action.type.name;
276	      throw new ArgumentError(action, `invalid ${typeName} value: ${reprStr(argString)}`);
277	    }
278	  }
279	}
