1	/**
2	 * The command-line interface of `test10.py`:
3	 *
4	 *     parser = argparse.ArgumentParser()
5	 *     parser.add_argument('--a', type=int, required=True)   # ... through '--e'
6	 */
7	
8	import { ArgumentParser } from './argparse.mjs';
9	import { pyInt } from '../python/int.mjs';
10	
11	/**
12	 * argparse takes `prog` from the program name. The reference build reports
13	 * `test10_executable`, so usage/error output stays byte-identical to it.
14	 */
15	export const PROG = 'test10_executable';
16	
17	export const ARGUMENT_NAMES = ['a', 'b', 'c', 'd', 'e'];
18	
19	export function buildParser(prog = PROG) {
20	  const parser = new ArgumentParser({ prog });
21	  for (const name of ARGUMENT_NAMES) {
22	    parser.addArgument([`--${name}`], { type: pyInt, required: true });
23	  }
24	  return parser;
25	}
26	
27	/** Parse `argv` (already stripped of the node/script entries) into `{a, b, c, d, e}`. */
28	export function parseArgs(argv, prog = PROG) {
29	  return buildParser(prog).parseArgs(argv);
30	}
